def apply(destination: Path) -> None:
    manifest_path=destination/'RELEASE_FILES.json'
    raw=manifest_path.read_bytes()
    if hashlib.sha256(raw).hexdigest()!=PARENT_MANIFEST_SHA256:
        raise ValueError('UI102 requires the exact UI101 source manifest. Do not deploy.')
    manifest=json.loads(raw)
    for name,expected in manifest['files'].items():
        relative=PurePosixPath(name)
        if relative.is_absolute() or '..' in relative.parts:
            raise ValueError('Unsafe source manifest path.')
        path=destination.joinpath(*relative.parts)
        if path.is_symlink() or not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest()!=expected:
            raise ValueError('UI102 parent resource mismatch: '+name)
    prepared={}
    for name,record in FILES.items():
        path=destination/name
        if record['before'] is None:
            if path.exists() or path.is_symlink() or name in manifest['files']:
                raise ValueError('UI102 new resource already exists: '+name)
        elif manifest['files'].get(name)!=record['before']:
            raise ValueError('UI102 parent file mismatch: '+name)
        dec=zlib.decompressobj()
        data=dec.decompress(base64.b64decode(record['payload'],validate=True),record['bytes']+1)
        data+=dec.flush()
        if not dec.eof or dec.unused_data or dec.unconsumed_tail or len(data)!=record['bytes'] or hashlib.sha256(data).hexdigest()!=record['after']:
            raise ValueError('UI102 payload integrity failure: '+name)
        prepared[name]=data
    for name,data in prepared.items():
        path=destination/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(data)
        manifest['files'][name]=FILES[name]['after']
    manifest['variant']=TARGET_VARIANT
    manifest_path.write_text(json.dumps(manifest,indent=2)+'\n')
    for name,expected in manifest['files'].items():
        if hashlib.sha256((destination/name).read_bytes()).hexdigest()!=expected:
            raise ValueError('Derived UI102 integrity failure: '+name)

if __name__=='__main__':
    apply(Path(sys.argv[1]))
    print('Applied Workspace UI102: shipping workbook and inventory-check search; prior imports, tabs, recovery and access retained.')
